  "player_descriptions": {
    "13": "Rudri, you had a solid game in midfield, contributing both offensively with a goal and defensively with crucial blocks. Your passing was on point, and you really helped control the flow in that area during our victory. Keep up that level of performance!",
    "9": "Kalyan, a hat-trick and an assist! You were an absolute menace in front of goal, causing all sorts of problems for the opposition leading us to victory. Keep that clinical edge and we'll be unstoppable!",
    "14": "Tarun, your goal and assist were vital for us in securing the win! You were always a threat going forward, and your work rate off the ball was equally impressive. Let's keep this momentum going forward, lad!",
    "3": "Rohan, your creativity was on full display with those assists! You were a constant threat, and those goals were well-deserved. Keep making those incisive passes and we'll keep racking up the goals!",
    "15": "Pillai, two goals and an assist. That's a fantastic performance that was key to our success in this match. You really stepped up and made a difference out there!",
    "11": "Mehtab, your contribution in midfield was crucial today, especially those vital blocks! Keep providing that support and we'll continue to dominate.",
    "6": "Tanay, you were an absolute rock in midfield, breaking up plays and protecting the defense with those tackles. Those assists were great as well! Keep up the fantastic work rate!",
    "16": "Bhukayo, seven goals?! What a performance that guided us to victory! You were simply unstoppable out there, keep terrorizing defenses like that!",
    "7": "Inder, though the ball didn't hit the net, your work rate and positioning were excellent and your assist helped secure the win. Keep getting into those dangerous areas, and the goals will come!",
    "2": "Lional, two goals and two assists - a fantastic contribution to the team's win. Your movement and finishing were top-notch, keep that up!",
    "10": "Bhuno, you put in a great shift in midfield. Your interceptions and blocks were crucial in disrupting the opposition's attacks, that goal was well deserved. Keep up that defensive awareness!",
    "12": "Alishan, you were an absolute wall in goal! So many saves kept us in control of the match, what a performance. Keep that focus and we'll be tough to beat!",
    "4": "Kavin, you were electric today, with goals, an assist and those dribbles driving us forward! Keep that energy and creativity flowing!",
    "5": "Prateek, your defensive work was top-notch, especially those tackles and blocks! Keep protecting that backline and the wins will keep coming.",
    "1": "Pitar, you were a safe pair of hands in goal today. Those saves were crucial in keeping the opposition at bay and helping us secure the win. Keep that concentration!",
    "8": "Hareesh, a hat-trick! You were lethal in front of goal, taking your chances with clinical precision, a true match winner. Keep those goals coming!",
    "18": "Krishnan, you contributed with an assist in this match. We appreciate you providing those key passes and creating those opportunities up front! Let's keep pushing forward.",
    "17": "Nikhil, your work rate was commendable. You're always a threat going forward, even if you didn't score, but those tackles are just as important!. Let's keep pushing forward."
  },
  "match_description": "What a match! Street Legends absolutely dismantled Ballers for Life, finishing with a staggering 18-7 victory! Kalyan Mbappi started strong early on with a quick goal, but Bhukayo Sarkar truly stole the show with an incredible seven goals, while Hareesh Khan also bagged a hat trick. Ballers for Life fought hard with Lional Masi managing a brace, but Street Legends relentless attack proved too much for them to handle today. It seems like Ballers for Life will need some tactical adjustments if they want to challenge Street Legends dominance.",
